def se_count(segments):
    # SE01 counts every segment in the transaction set, including ST and SE.
    return len(segments) + 1   # +1 for the SE segment itself

def escape(value, delims, release="?"):
    out = []
    for ch in value:
        if ch in delims:
            out.append(release)
        out.append(ch)
    return "".join(out)

def process(raw: bytes, partner: str) -> Result:
    archive(raw, partner)                       # 1. raw bytes first, always
    d = read_delimiters(raw.decode("latin-1"))  # 2. delimiters from the ISA
    env = parse_envelopes(raw, d)               # 3. ISA/GS/ST structure
    if seen_before(partner, env.control_numbers, sha256(raw)):
        return Result.duplicate(env)            # 4. idempotency, before effects
    errors = validate(env, profile_for(partner))
    if errors:
        return Result.rejected(env, errors, ack=build_997(env, errors))
    order = to_canonical(env)                   # 5. map
    publish(order)                              # 6. route downstream
    return Result.accepted(env, ack=build_997(env, []))
